const std = @import("std"); const builtin = @import("builtin"); const regi = @import("registry"); const stre = @import("stream"); const cwdi = @import("cwd"); const stor = @import("store");
const ruspawbase = @import("ru-spaw-base.zig"); const CF = ruspawbase.CF; const CMDZ_ENVI_VARZ = ruspawbase.CMDZ_ENVI_VARZ; const TIME_CODE = ruspawbase.TIME_CODE; const chilSpaw = ruspawbase.chilSpaw; const enviExpa = ruspawbase.enviExpa; const mute_spaw = ruspawbase.mute_spaw; const nowzMsec = ruspawbase.nowzMsec; const runzCapt = ruspawbase.runzCapt;
pub const ShelKind = enum { defa, cmdz, powe, pwsh, bash, bash_logi, shzz, zshz, fish, wslz };
pub fn shelPars(strz: []const u8) ShelKind { const mapz = .{ .{ "cmd", ShelKind.cmdz }, .{ "powershell", ShelKind.powe }, .{ "pwsh", ShelKind.pwsh }, .{ "bash", ShelKind.bash }, .{ "bash-login", ShelKind.bash_logi }, .{ "sh", ShelKind.shzz }, .{ "zsh", ShelKind.zshz }, .{ "fish", ShelKind.fish }, .{ "wsl", ShelKind.wslz } }; inline for (mapz) |item| if (std.mem.eql(u8, strz, item[0])) return item[1]; return .defa; }
pub fn argvBuil(allo: std.mem.Allocator, kind: ShelKind, cmdz: []const u8) ![]const []const u8 { const wind = builtin.os.tag == .windows; const boot = "%" ++ CF.envi_name ++ "%"; return switch (kind) { .cmdz => try allo.dupe([]const u8, &.{ "cmd.exe", "/d", "/c", boot }), .powe => try allo.dupe([]const u8, &.{ "powershell.exe", "-NoLogo", "-NoProfile", "-NonInteractive", "-Command", cmdz }), .pwsh => try allo.dupe([]const u8, &.{ "pwsh", "-NoLogo", "-NoProfile", "-NonInteractive", "-Command", cmdz }), .bash => try allo.dupe([]const u8, &.{ "bash", "-c", cmdz }), .bash_logi => try allo.dupe([]const u8, &.{ "bash", "-lc", cmdz }), .shzz => try allo.dupe([]const u8, &.{ "sh", "-c", cmdz }), .zshz => try allo.dupe([]const u8, &.{ "zsh", "-c", cmdz }), .fish => try allo.dupe([]const u8, &.{ "fish", "-c", cmdz }), .wslz => try allo.dupe([]const u8, &.{ "wsl.exe", "-e", "sh", "-c", cmdz }), .defa => if (wind) try allo.dupe([]const u8, &.{ "cmd.exe", "/d", "/c", boot }) else try allo.dupe([]const u8, &.{ shelUser(), "-c", cmdz }) }; }
var shel_user_buff: [CF.shel_buff]u8 = undefined; var shel_user_leng: std.atomic.Value(usize) = .init(0);
fn shelUser() []const u8 { const leng = shel_user_leng.load(.acquire); if (leng > 0) return shel_user_buff[0..leng]; const valz = std.c.getenv("SHELL"); var pick: []const u8 = "sh"; if (valz) |ptrz| { const strz = std.mem.span(ptrz); const base = std.fs.path.basename(strz); const know = [_][]const u8{ "bash", "zsh", "fish", "dash", "sh", "ksh", "ash" }; if (strz.len > 0 and strz[0] == '/' and strz.len < shel_user_buff.len) { for (know) |item| if (std.mem.eql(u8, base, item)) { pick = strz; break; }; } } @memcpy(shel_user_buff[0..pick.len], pick); shel_user_leng.store(pick.len, .release); return shel_user_buff[0..pick.len]; }
pub fn cmdzBootUses(kind: ShelKind) bool { if (builtin.os.tag != .windows) return false; return kind == .cmdz or kind == .defa; }
pub fn shelAvai(allo: std.mem.Allocator, iozz: std.Io) []const []const u8 { var outz: std.ArrayList([]const u8) = .empty; const cand: []const []const u8 = if (builtin.os.tag == .windows) &.{ "cmd", "powershell", "pwsh", "bash", "wsl" } else &.{ "sh", "bash", "zsh", "fish", "pwsh" }; for (cand) |name| { const exez = if (std.mem.eql(u8, name, "cmd") or std.mem.eql(u8, name, "sh") or std.mem.eql(u8, name, "powershell")) true else pathHasz(allo, iozz, name); if (exez) outz.append(allo, name) catch {}; } if (builtin.os.tag != .windows and pathHasz(allo, iozz, "bash")) outz.append(allo, "bash-login") catch {}; return outz.toOwnedSlice(allo) catch &.{}; }
fn pathHasz(allo: std.mem.Allocator, iozz: std.Io, name: []const u8) bool { const path = std.process.Environ.getAlloc(stor.enviLive(), allo, "PATH") catch return false; const sepa: u8 = if (builtin.os.tag == .windows) ';' else ':'; var iter = std.mem.splitScalar(u8, path, sepa); while (iter.next()) |dirz| { if (dirz.len == 0) continue; const file = if (builtin.os.tag == .windows) std.fmt.allocPrint(allo, "{s}\\{s}.exe", .{ dirz, name }) catch continue else std.fmt.allocPrint(allo, "{s}/{s}", .{ dirz, name }) catch continue; _ = std.Io.Dir.cwd().statFile(iozz, file, .{}) catch continue; return true; } return false; }
